import type React from 'react'

import {clsx} from 'clsx'

import styles from './UI.module.css'

export function EllipsisOverflow(props: React.PropsWithChildren<{title: string}>) {
  return (
    // eslint-disable-next-line github/a11y-no-title-attribute
    <div title={props.title} className={styles.ellipsisOverflow}>
      {props.children}
    </div>
  )
}

export function CenteredContent(props: React.PropsWithChildren<{className?: string}>) {
  return <div className={clsx(styles.centeredContent, props.className)}>{props.children}</div>
}

export function TextWithIcon(props: React.PropsWithChildren<{icon: React.ReactNode; className?: string}>) {
  return (
    <CenteredContent>
      {props.icon}
      <span className={props.className}>{props.children}</span>
    </CenteredContent>
  )
}
