import type React from 'react'

import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'
import {Link} from '@primer/react'
import {clsx} from 'clsx'
import {useFileContext} from './context'

import styles from './Snippet.module.css'

export type CodeLine = {
  /** A pre-colorized line of code */
  html: SafeHTMLString
  /** This line of code's line number */
  number: number
}

export function Snippet(props: {lines: CodeLine[]}) {
  const file = useFileContext()

  const lines: React.ReactNode[] = []

  for (const line of props.lines) {
    lines.push(
      <tr key={line.number} role="row">
        <td role="cell">
          <Link href={`${file.fileUrl}/#L${line.number}`} className={clsx('blob-num', styles.blobNumLink)}>
            {line.number}
          </Link>
        </td>
        <VerifiedHTMLText
          as="td"
          className={`blob-code blob-code-inner ${styles.codeSnippetLine}`}
          role="cell"
          html={line.html}
        />
      </tr>,
    )
  }

  return (
    <div className={clsx('code-list', 'notranslate', styles.snippetContainer)}>
      <table role="table">
        {
          // We need to add role="rowgroup" because we don't have table headers
          // And in order to screen readers to know that we really mean for this to be a table
          // We must define it explicitly
          <tbody role="rowgroup">{lines}</tbody>
        }
      </table>
    </div>
  )
}
